# -*- coding: utf-8 -*-
"""
首次覆盖事件驱动策略（QuantStudio 移植版）
=================================================================
信号：券商研报「首次覆盖」评级（买入 / 增持）作为事件信号。
逻辑：
  1) 信号 T+1 交易日生效（PIT 安全，1 天有效期）；
  2) 前置 R4 实盘合规过滤：ST / 停牌 / 次新(<365日) / 科创(688) / 北交所(8/4/9)
     行业剔除（银行/证券/保险/金融/电力/公用事业/供水/供气/供热）/ 央国企白名单剔除；
  3) 资金等分 BATCH_NUM 份，批次轮动；每批至多 MAX_HOLD 只、单行业至多 MAX_INDUSTRY 只；
  4) 建仓后持有 HOLD_DAYS 个交易日到期清仓；
  5) 持仓期日内三段式止损止盈（low 止损 / high 止盈 / close 保底，涨停持有止盈）；
  6) 止损触发标的进入全策略黑名单，永不再买。
对标基准：沪深300（000300.XSHG）；初始资金：10 万元。
说明：本框架策略零 import、禁止直连数据库，所有行情经注入 API 取数；
      研报信号优先读取 SIGNAL_CSV_PATH 指定的每日更新 CSV（仅买入/增持），缺失时回退内嵌 _RAW_SIGNALS。
撮合说明：本移植在日线回测下按「当日收盘」即时撮合（近似原策略 T+1 开盘买入）。
"""

# ---------------- 可调参数（可直接修改，或在 initialize 顶部覆盖）----------------
BATCH_NUM = 3          # 批次数量（资金等分份数 / 最大并发组数），1=单批满仓
HOLD_DAYS = 3          # 单批持有交易日数，到期清仓
MAX_HOLD = 4           # 单批最大持仓只数
MAX_INDUSTRY = 2       # 单批内同一行业最大持仓只数
STOP_LOSS = -0.05      # 止损线（相对成本价，负=跌幅）
TAKE_PROFIT = 0.10     # 止盈线（相对成本价，正=涨幅）
MIN_BATCH_CASH = 2000  # 批次可用资金低于此值不建仓

# 成本模型（对齐原策略）
SLIP = 0.001
COMM = 0.0003
MIN_COMM = 5.0
STAMP = 0.001

# R4：行业剔除
INDUSTRY_EXCLUDE = ['银行', '证券', '保险', '金融', '电力', '公用事业', '供水', '供气', '供热']
# R4：央国企白名单（裸码），命中即剔除
SOE_FILTER = {
    '600028', '601857', '600938', '600941', '600050', '601728', '601398', '601939',
    '601288', '601988', '601658', '600036', '601166', '601916', '601998', '601818',
    '601318', '601628', '601601', '601336', '601668', '601390', '601186', '601800',
    '601669', '601868', '601766', '600150', '601989', '601088', '600795', '600011',
    '600027', '601919', '600428', '601872', '600030', '600837', '601211', '601688',
}

# 首次覆盖研报信号：经框架注入 API load_research_signals 读取每日更新的研报 CSV
# （仅保留 买入/增持），CSV 缺失/解析失败回退到下方内嵌 _RAW_SIGNALS 快照。
# 注：策略文件受 StrategyIsolationGuard 约束，禁止直接 open()/read_csv()，文件 I/O
#     必须经由注入 API（load_research_signals）完成，否则加载即报 StrategyIsolationError。
