def initialize(context):
    set_benchmark("000300.XSHG")
    g.batch_num = BATCH_NUM
    g.hold_days = HOLD_DAYS
    g.max_hold = MAX_HOLD
    g.max_industry = MAX_INDUSTRY
    g.stop_loss = STOP_LOSS
    g.take_profit = TAKE_PROFIT
    g.min_batch_cash = MIN_BATCH_CASH
    g.init_cash = context.portfolio.total_value
    g.batch_capital = g.init_cash / g.batch_num
    g.blacklist = set()
    g.batches = [{'id': i + 1, 'cash': g.batch_capital, 'holdings': {},
                  'active': False, 'trade_days': 0}
                 for i in range(g.batch_num)]
    # 注意：get_trade_days() 无参时 end 取 self._current_date（initialize 阶段=回测首日），
    # 会导致日历止于首日、信号日程丢失首日之后的所有信号。因此显式传宽区间。
    g.trade_days = sorted(str(d)[:10] for d in
                          get_trade_days(start_date='1990-01-01', end_date='2100-01-01'))
    g.signals_by_date = _build_signal_schedule()
    if not is_trade():
        set_backtest()


def set_backtest():
    try:
        set_limit_mode("UNLIMITED")
    except Exception:
        pass


def _build_signal_schedule():
    # 通过框架注入 API 读取研报 CSV（策略内禁止直接文件 I/O）
    raw, src = load_research_signals(SIGNAL_CSV_PATH, fallback=list(_RAW_SIGNALS))
    try:
        log.info(f"[首次覆盖] 信号来源={src} 原始条数={len(raw)}")
    except Exception:
        pass
    sched = {}
    first_day = g.trade_days[0] if g.trade_days else ""
    for code6, name, industry, pub in raw:
        if pub < first_day:   # 跳过早于回测窗口的研报，避免首日堆积
            continue
        eff = _next_trade_day(g.trade_days, pub)
        if eff is None:
            continue
        sched.setdefault(eff, []).append((code6, name, industry))
    return sched


def _next_trade_day(cal, pub):
    # 返回严格晚于 pub 的首个交易日（cal 为升序 ISO 日期字符串列表）
    lo, hi = 0, len(cal) - 1
    ans = None
    while lo <= hi:
        mid = (lo + hi) // 2
        if cal[mid] > pub:
            ans = cal[mid]
            hi = mid - 1
        else:
            lo = mid + 1
    return ans


def _norm(code6):
    return code6 + ".XSHG" if code6.startswith("6") else code6 + ".XSHE"


def _bar(data, code):
    try:
        return data[code]
    except Exception:
        return None


def _is_st(code):
    try:
        passed = filter_stock_by_status([code], ["ST"])
        bare = code.split(".")[0]
        return not any(c.split(".")[0] == bare for c in passed)
    except Exception:
        return False


def _is_suspended(code):
    try:
        passed = filter_stock_by_status([code], ["HALT"])
        bare = code.split(".")[0]
        return not any(c.split(".")[0] == bare for c in passed)
    except Exception:
        return False


def _is_limit_up(code):
    try:
        cl = check_limit(code)
        if isinstance(cl, dict):
            vals = list(cl.values())
            return bool(vals) and vals[0] == 1
        return cl == 1
    except Exception:
        return False


def _is_new(code, today):
    try:
        info = get_security_info(code)
        sd = getattr(info, "list_date", None) or getattr(info, "start_date", None)
        if not sd:
            return False
        listed = pd.Timestamp(str(sd))
        cur = pd.Timestamp(today)
        return (cur - listed).days < 365
    except Exception:
        return False


def handle_data(context, data):
    today = context.current_dt.strftime("%Y-%m-%d")
    # Step1：持仓三段式止损止盈
    for b in g.batches:
        if b["active"] and b["holdings"]:
            _check_stop(context, data, b, today)
    # Step2：持有期满清仓
    for b in g.batches:
        if b["active"]:
            b["trade_days"] += 1
            if b["trade_days"] >= g.hold_days:
                _liquidate(context, data, b, today)
            if b["active"] and not b["holdings"]:
                b["active"] = False
                b["trade_days"] = 0
    # Step3：当日信号 -> 首个可用批次建仓
    if today in g.signals_by_date:
        sigs = g.signals_by_date[today]
        for b in g.batches:
            if (not b["active"]) and b["cash"] >= g.min_batch_cash:
                _buy_batch(context, data, b, sigs, today)
                break


def _check_stop(context, data, b, today):
    for code in list(b["holdings"].keys()):
        h = b["holdings"][code]
        cost = h["cost"]
        bar = _bar(data, code)
        if bar is None or bar.close <= 0:
            continue
        close_p = bar.close
        low_p = bar.low
        high_p = bar.high
        # 1) low 触发止损（不查涨停）
        if low_p > 0 and (low_p - cost) / cost <= g.stop_loss:
            _sell(context, data, b, code, close_p, "止损")
            continue
        # 2) high 触发止盈（涨停持有）
        if high_p > 0 and (high_p - cost) / cost >= g.take_profit:
            if _is_limit_up(code):
                continue
            _sell(context, data, b, code, close_p, "止盈")
            continue
        # 3) close 保底
        close_pct = (close_p - cost) / cost
        if close_pct <= g.stop_loss:
            _sell(context, data, b, code, close_p, "止损")
        elif close_pct >= g.take_profit:
            if not _is_limit_up(code):
                _sell(context, data, b, code, close_p, "止盈")


def _liquidate(context, data, b, today):
    for code in list(b["holdings"].keys()):
        bar = _bar(data, code)
        price = bar.close if (bar is not None and bar.close > 0) else None
        if price is None:
            continue  # 停牌无法卖出，保留至复牌
        _sell(context, data, b, code, price, "到期")


def _sell(context, data, b, code, price, reason):
    h = b["holdings"].get(code)
    if h is None:
        return False
    o = order_target_value(code, 0)
    if o is None or (hasattr(o, "status") and o.status == "rejected"):
        return False
    shares = h["shares"]
    exec_price = price * (1 - SLIP)
    amount = shares * exec_price
    fee = max(amount * COMM, MIN_COMM)
    tax = amount * STAMP
    b["cash"] += amount - fee - tax
    profit_pct = (exec_price - h["cost"]) / h["cost"] * 100
    del b["holdings"][code]
    if reason == "止损":
        g.blacklist.add(code)
    log.info(f"卖出 {code} 股数{shares} 盈亏{profit_pct:.2f}% 原因={reason}")
    return True


def _buy_batch(context, data, b, signals, today):
    valid = []
    ind_count = {}
    for code6, name, industry in signals:
        code = _norm(code6)
        if code in b["holdings"]:
            continue
        if code in g.blacklist:
            continue
        if code6.startswith(("688", "8", "4", "9")):
            continue
        if code6 in SOE_FILTER:
            continue
        if _is_st(code) or _is_suspended(code):
            continue
        if _is_new(code, today):
            continue
        if _is_limit_up(code):
            continue
        bar = _bar(data, code)
        if bar is None or bar.close <= 0:
            continue
        if industry in INDUSTRY_EXCLUDE:
            continue
        if ind_count.get(industry, 0) >= g.max_industry:
            continue
        valid.append((code, name, industry, bar.close))
        ind_count[industry] = ind_count.get(industry, 0) + 1
        if len(valid) >= g.max_hold:
            break
    if not valid:
        return 0
    # 第一轮：n_buy 自适应等权
    best_n = 1
    for try_n in range(min(len(valid), g.max_hold), 0, -1):
        test_cash = b["cash"]
        test_count = 0
        for i in range(try_n):
            price = valid[i][3]
            exec_price = price * (1 + SLIP)
            shares = int(b["cash"] / try_n / exec_price / 100) * 100
            if shares < 100:
                continue
            amount = shares * exec_price
            fee = max(amount * COMM, MIN_COMM)
            test_cash -= (amount + fee)
            test_count += 1
        if test_count == 0:
            continue
        total_cost = b["cash"] - test_cash
        idle_ratio = total_cost / b["cash"]
        if idle_ratio >= 0.95:
            best_n = try_n
            break
    n_buy = min(best_n, len(valid))
    per_cash = b["cash"] / n_buy if n_buy > 0 else b["cash"]
    bought = 0
    for i in range(n_buy):
        code, name, industry, price = valid[i]
        bought += _exec_buy(context, b, code, name, industry, price, per_cash, today)
    # 第二轮：剩余现金继续买入未持仓
    if b["cash"] >= 3000 and len(b["holdings"]) < g.max_hold:
        remaining = [v for v in valid if v[0] not in b["holdings"]]
        for code, name, industry, price in remaining:
            if len(b["holdings"]) >= g.max_hold:
                break
            if b["cash"] < 2000:
                break
            bought += _exec_buy(context, b, code, name, industry, price, b["cash"], today, allow_all=True)
    if bought > 0:
        b["active"] = True
        b["trade_days"] = 0
    return bought


def _exec_buy(context, b, code, name, industry, price, budget, today, allow_all=False):
    exec_price = price * (1 + SLIP)
    shares = int(budget / exec_price / 100) * 100
    if shares < 100:
        if not allow_all:
            return 0
        shares = 100
    amount = shares * exec_price
    fee = max(amount * COMM, MIN_COMM)
    cost = amount + fee
    if cost > b["cash"]:
        if not allow_all:
            return 0
        shares = int((b["cash"] - 100) / exec_price / 100) * 100
        if shares < 100:
            return 0
        amount = shares * exec_price
        fee = max(amount * COMM, MIN_COMM)
        cost = amount + fee
    o = order(code, shares)
    if o is None or (hasattr(o, "status") and o.status == "rejected"):
        return 0
    fill_price = getattr(o, "price", exec_price) or exec_price
    real_cost = shares * fill_price + max(shares * fill_price * COMM, MIN_COMM)
    b["cash"] -= real_cost
    b["holdings"][code] = {"shares": shares, "cost": exec_price,
                           "entry": today, "name": name, "industry": industry}
    log.info(f"买入 {code} {name} {shares}股 成本{exec_price:.2f}")
    return 1
